#include <stdio.h>
#include <nb.h>

/* A second opinion. C reads the edge list straight from nb (the Python cell
   published it flat: u0, v0, u1, v1, ...) and counts things its own way. */
int flat[400];
int parent[64];
int has[64][64];
int deg[64];

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];   /* path halving keeps the trees flat */
        x = parent[x];
    }
    return x;
}

int main() {
    int n = (int)nb_get_int("graph_n", 0);
    int len = nb_get_ints("graph_flat", flat, 400);
    if (n <= 0 || n > 64 || len < 0) {
        printf("Run the Python cell first: it publishes the graph.\n");
        return 0;
    }
    int m = len / 2;

    /* Union-find over the EDGE LIST: components without building any adjacency structure. */
    for (int i = 0; i < n; i++) parent[i] = i;
    for (int k = 0; k < m; k++) parent[find(flat[2 * k])] = find(flat[2 * k + 1]);
    int components = 0;
    for (int i = 0; i < n; i++) if (find(i) == i) components++;

    /* Triangles want O(1) "are these two joined?": that is MATRIX territory. */
    for (int k = 0; k < m; k++) {
        int u = flat[2 * k], v = flat[2 * k + 1];
        has[u][v] = has[v][u] = 1;
        deg[u]++; deg[v]++;
    }
    int triangles = 0;
    for (int i = 0; i < n; i++)
        for (int j = i + 1; j < n; j++) {
            if (!has[i][j]) continue;
            for (int k = j + 1; k < n; k++)
                if (has[i][k] && has[j][k]) triangles++;
        }

    printf("C read %d nodes and %d edges from nb\n", n, m);
    printf("components: %d  triangles: %d\n", components, triangles);
    printf("__NB_SET__ {\"key\":\"graph_second\",\"value\":{\"lang\":\"C\",\"components\":%d,\"triangles\":%d,\"degrees\":[",
           components, triangles);
    for (int i = 0; i < n; i++) printf(i ? ",%d" : "%d", deg[i]);
    printf("]}}\n");
    return 0;
}

// Cross-examine: recompute everything from nb's edge list in JS and
// compare with the second language's independent run.
const graph = nb.get('graph');
if (!graph) return 'Run the Python cell first.';
const n = graph.nodes.length;

const deg = new Array(n).fill(0);
const has = Array.from({ length: n }, () => new Array(n).fill(false));
for (const [u, v] of graph.edges) {
  deg[u]++; deg[v]++;
  has[u][v] = has[v][u] = true;
}

// components via BFS over an adjacency list built from the same edges
const adj = Array.from({ length: n }, () => []);
for (const [u, v] of graph.edges) { adj[u].push(v); adj[v].push(u); }
const seen = new Array(n).fill(false);
let components = 0;
for (let s = 0; s < n; s++) {
  if (seen[s]) continue;
  components++;
  const q = [s]; seen[s] = true;
  while (q.length) {
    const u = q.shift();
    for (const v of adj[u]) if (!seen[v]) { seen[v] = true; q.push(v); }
  }
}

let triangles = 0;
for (let i = 0; i < n; i++)
  for (let j = i + 1; j < n; j++)
    if (has[i][j])
      for (let k = j + 1; k < n; k++)
        if (has[i][k] && has[j][k]) triangles++;

console.log('JS recount: components =', components, ', triangles =', triangles);

const go = nb.get('graph_second');
if (!go) {
  console.log('The second-opinion cell has not run yet, so there is nothing to cross-check.');
  return { components, triangles, crossChecked: false };
}
const degreesMatch = JSON.stringify(go.degrees) === JSON.stringify(deg);
console.log(go.lang + ' agrees on components:', go.components === components,
  '- triangles:', go.triangles === triangles, '- degrees:', degreesMatch);
return {
  components, triangles,
  crossChecked: true,
  agree: go.components === components && go.triangles === triangles && degreesMatch,
};

// Measure the three representations on random graphs of growing size.
function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const rows = [];
console.log('nodes   edges   list ints   matrix cells   BFS steps: list   matrix   edge list');
for (const n of [50, 100, 200, 400, 800, 1600]) {
  const rand = mulberry32(n), m = 2 * n;            // about 4 neighbours each, like a sparse network
  const edges = [];
  const seen = new Set();
  while (edges.length < m) {
    const u = Math.floor(rand() * n), v = Math.floor(rand() * n);
    if (u === v || seen.has(u * n + v) || seen.has(v * n + u)) continue;
    seen.add(u * n + v);
    edges.push([u, v]);
  }
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }

  // BFS work, counted as neighbour checks, for each representation
  function bfs(neighbours) {
    const seenNodes = new Uint8Array(n), queue = [0];
    seenNodes[0] = 1;
    let work = 0;
    while (queue.length) {
      const u = queue.shift();
      work += neighbours(u, v => { if (!seenNodes[v]) { seenNodes[v] = 1; queue.push(v); } });
    }
    return work;
  }
  const listWork = bfs((u, visit) => { adj[u].forEach(visit); return adj[u].length; });
  const matrixWork = bfs((u, visit) => { for (let v = 0; v < n; v++) if (adj[u].includes(v)) visit(v); return n; });   // a matrix row has n cells
  const edgeWork = bfs((u, visit) => { for (const [a, b] of edges) { if (a === u) visit(b); else if (b === u) visit(a); } return m; });

  rows.push({ n, value: 2 * m, what: 'memory: adjacency list (ints)' });
  rows.push({ n, value: n * n, what: 'memory: matrix (cells)' });
  rows.push({ n, value: listWork, what: 'BFS: adjacency list' });
  rows.push({ n, value: matrixWork, what: 'BFS: matrix' });
  rows.push({ n, value: edgeWork, what: 'BFS: edge list' });
  console.log(String(n).padStart(5) + String(m).padStart(8) + String(2 * m).padStart(12) + String(n * n).padStart(15) +
    String(listWork).padStart(19) + String(matrixWork).padStart(9) + String(edgeWork).padStart(12));
}

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  width: 'container',
  height: 300,
  title: 'Sparse graphs (about 4 neighbours each): what each way costs',
  data: { values: rows },
  mark: { type: 'line', point: true },
  encoding: {
    x: { field: 'n', type: 'quantitative', scale: { type: 'log' }, title: 'nodes (log scale)' },
    y: { field: 'value', type: 'quantitative', scale: { type: 'log' }, title: 'ints stored, or neighbour checks (log scale)' },
    color: { field: 'what', type: 'nominal', title: null },
    strokeDash: { condition: { test: "indexOf(datum.what, 'memory') === 0", value: [5, 4] }, value: [1, 0] },
  },
};
